#!/usr/bin/env python3
import os
import sys
import base64
import subprocess
import shutil
from pathlib import Path

# Embedded files (base64 encoded)
FILES = {'app.py': '', 'config.py': '', 'engine.py': '', 'processor.py': '', 'storage.py': '', 'requirements.txt': 'ZmFzdGFwaT09MC4xMTUuNgp1dmljb3JuW3N0YW5kYXJkXT09MC4zNC4wCnB5dGhvbi1tdWx0aXBhcnQ9PTAuMC4yMAppbnNpZ2h0ZmFjZT09MC43LjMKb25ueHJ1bnRpbWU+PTEuMjAuMQpvcGVuY3YtcHl0aG9uLWhlYWRsZXNzPT00LjEwLjAuODQKbnVtcHkKUGlsbG93PT0xMS4wLjAKcGlsbG93LWhlaWY9PTAuMjEuMAptbC1kdHlwZXM+PTAuNS4wCg==', 'run.sh': '', 'run.bat': '', 'static/index.html': '', 'static/app.js': '', 'static/style.css': ''}

def main():
    print("=== FaceSort Bootstrap & Deployment Tool ===")
    
    # 1. Environment Checks
    print("\n[1/4] Checking environment...")
    
    # Check Python version (>= 3.10)
    major, minor = sys.version_info[:2]
    if (major, minor) < (3, 10):
        print(f"ERROR: Python 3.10 or newer is required. You are running {sys.version}.", file=sys.stderr)
        sys.exit(1)
    print(f"  Python version: {sys.version.split()[0]} (OK)")

    # Check for NVIDIA GPU presence
    has_nvidia = False
    try:
        if shutil.which("nvidia-smi") is not None:
            has_nvidia = True
            print("  NVIDIA GPU detected (nvidia-smi is available).")
    except Exception:
        pass

    # 2. Write project files
    print("\n[2/4] Writing application files to current directory...")
    current_dir = Path.cwd()
    for rel_path_str, b64_content in FILES.items():
        rel_path = current_dir / rel_path_str
        rel_path.parent.mkdir(parents=True, exist_ok=True)
        
        file_bytes = base64.b64decode(b64_content.encode("utf-8"))
        if rel_path_str == "requirements.txt" and has_nvidia:
            try:
                req_text = file_bytes.decode("utf-8")
                # Swap onnxruntime with CUDA 12-pinned onnxruntime-gpu
                req_text = req_text.replace("onnxruntime>=1.20.1", "onnxruntime-gpu==1.20.0")
                
                # Append pip CUDA/cuDNN cu12 runtime libraries to requirements.txt (force cuDNN 9+)
                req_text += "\nnvidia-cuda-runtime-cu12\nnvidia-cublas-cu12\nnvidia-cudnn-cu12>=9.0.0\n"
                
                file_bytes = req_text.encode("utf-8")
                print("  [Auto-config] Switched to onnxruntime-gpu==1.20.0 (CUDA 12) and pinned nvidia-cudnn-cu12>=9.0.0.")
            except Exception as e:
                print(f"  [Warning] Failed to patch requirements.txt for GPU: {e}")
                
        print(f"  Writing {rel_path_str}...")
        rel_path.write_bytes(file_bytes)

    # Set execute permission on run.sh
    sh_script = current_dir / "run.sh"
    if sh_script.exists():
        try:
            sh_script.chmod(0o755)
        except Exception:
            pass

    # 3. Create virtual environment
    print("\n[3/4] Creating virtual environment (.venv)...")
    venv_dir = current_dir / ".venv"
    new_req_path = current_dir / "requirements.txt"
    installed_req_path = venv_dir / "installed_requirements.txt"

    requirements_changed = False
    if venv_dir.exists():
        if not installed_req_path.exists():
            requirements_changed = True
        else:
            try:
                if new_req_path.read_text(encoding="utf-8") != installed_req_path.read_text(encoding="utf-8"):
                    requirements_changed = True
            except Exception:
                requirements_changed = True
                
        if requirements_changed:
            print("  [Auto-clean] Requirements changed. Deleting old virtual environment for clean setup...")
            try:
                shutil.rmtree(venv_dir, ignore_errors=True)
            except Exception as e:
                print(f"  [Warning] Failed to delete old .venv: {e}")
        else:
            print("  .venv already exists and requirements match, skipping recreation.")

    if not venv_dir.exists():
        try:
            import venv
            venv.create(".venv", with_pip=True)
            print("  Created virtual environment (.venv) successfully.")
        except ImportError:
            # Fall back to subprocess
            print("  python3 venv module missing, trying virtualenv command...")
            try:
                subprocess.run([sys.executable, "-m", "venv", ".venv"], check=True)
                print("  Created .venv successfully.")
            except Exception as e:
                print(f"ERROR: Failed to create virtual environment: {e}", file=sys.stderr)
                sys.exit(1)

    # 4. Install requirements
    print("\n[4/4] Installing dependencies from requirements.txt...")
    pip_path = venv_dir / "bin" / "pip" if os.name != "nt" else venv_dir / "Scripts" / "pip"
    python_path = venv_dir / "bin" / "python" if os.name != "nt" else venv_dir / "Scripts" / "python"

    if not pip_path.exists():
        # Try finding standard pip location on Windows
        if os.name == "nt":
            pip_path = venv_dir / "Scripts" / "pip.exe"
            python_path = venv_dir / "Scripts" / "python.exe"

    try:
        print("  Upgrading pip...")
        subprocess.run([str(python_path), "-m", "pip", "install", "--upgrade", "pip"], check=True)
        print("  Installing packages (this might take a few minutes)...")
        subprocess.run([str(pip_path), "install", "-r", "requirements.txt"], check=True)
        print("  Dependencies installed successfully.")
        
        # Save checksum file to remember installed state
        try:
            shutil.copyfile(new_req_path, installed_req_path)
        except Exception:
            pass
            
    except Exception as e:
        print(f"ERROR: Failed to install dependencies: {e}", file=sys.stderr)
        sys.exit(1)

    # Launching the application
    print("\n=== Setup Complete ===")
    print("Starting FaceSort server...")
    print("--------------------------------------------------")
    print("  FaceSort is now running at: http://0.0.0.0:9090")
    print("--------------------------------------------------")
    
    app_py_path = current_dir / "app.py"
    if not app_py_path.exists():
        print("ERROR: app.py not found in working directory.", file=sys.stderr)
        sys.exit(1)

    try:
        subprocess.run([str(python_path), "app.py"])
    except KeyboardInterrupt:
        print("\nServer stopped.")

if __name__ == "__main__":
    main()
